{"code":"await write(T+'/src/main.rs',`use ulw_bench_fixture::parser_a::*; use ulw_bench_fixture::parser_b::*;
use std::time::Instant;
fn main(){
 for s in ["1+2","1+2-3","10-4+2","1+2 +3","1+","1+2x"] { println!("A {:?} => {:?}", s, RecursiveDescentParser::new(s).parse()); }
 let n:usize=std::env::args().nth(2).unwrap().parse().unwrap();
 match std::env::args().nth(1).unwrap().as_str() {
  "a"=>{let big=(0..n).map(|_|"1").collect::<Vec<_>>().join("+");let t=Instant::now();let r=RecursiveDescentParser::new(&big).parse();println!("A parse {} terms ok={} {:?}",n,r.is_ok(),t.elapsed());std::mem::forget(r);println!("A forgot tree, no overflow");}
  _=>{let toks:Vec<String>=(0..n).flat_map(|i|if i==0{vec!["1".to_string()]}else{vec!["+".to_string(),"1".to_string()]}).collect();let t=Instant::now();let r=ShiftReduceParser::parse(&toks);println!("B parse {} terms ok={} {:?}",n,r.is_ok(),t.elapsed());std::mem::forget(r);println!("B forgot tree, no overflow");}
 }
}`);
const env={...process.env,TMPDIR:T,CARGO_TARGET_DIR:T+'/t'};
print(await Bun.$`cd ${T} && cargo build -q --release 2>&1 | tail -5; for a in "a 200000" "b 200000" "a 1000000" "b 1000000"; do echo "# $a"; ./t/release/ulw-bench-fixture $a 2>&1 | tail -4; done`.env(env).nothrow().text());","language":"js","summary":"Probe unspaced input and parse-vs-drop stack behavior","timeout":180}

